fun Cocktail_Sort(@init<table> array):
    n = length(array)

    // Set up left and right boundaries for the unsorted portion
    left = 0
    right = n - 1

    // Continue sorting while there are elements to sort
    while (left < right):
        swapped = False

        // Pass from left to right (bubble largest to the right)
        for (i = left; i < right; i += 1):
            @mark<i, outline, yellow> if (array[i] > array[i + 1]):
                @mark<i, highlight, green> swap(array[i], array[i + 1])
                swapped = True
            end if
        end for

        // Reduce the right boundary since the largest element is now in place
        right -= 1

        // If no swaps occurred, the array is sorted
        if (swapped == False):
            break
        end if

        // Pass from right to left (bubble smallest to the left)
        for (i = right; i > left; i -= 1):
            @mark<i, outline, yellow> if (array[i] < array[i - 1]):
                @mark<i, highlight, green> swap(array[i], array[i - 1])
                swapped = True
            end if
        end for

        // Increase the left boundary since the smallest element is now in place
        left += 1

        // If no swaps occurred, the array is sorted
        if (swapped == False):
            break
        end if
    end while

    return array
end fun

