fun Dutch_Flag_Sort(@init<table> array):
    n = length(array)

    // Three pointers: low, mid, high
    low = 0
    mid = 0
    high = n - 1

    // Loop until mid crosses high
    while (mid <= high):
        @mark<mid, outline, yellow> if (array[mid] == 0):
            // Found 0, swap with low pointer
            @mark<low, highlight, green> swap(array[low], array[mid])
            low += 1
            mid += 1
        else if (array[mid] == 1):
            // Found 1, leave in place
            mid += 1
        else:
            // Found 2, swap with high pointer
            @mark<high, highlight, green> swap(array[mid], array[high])
            high -= 1
            // Do not increment mid here since swapped element from high may be 0 or 2
        end if
    end while

    return array
end fun

