fun Heapify(@init<table> array, n, i):
    @mark<i, outline, yellow> largest = i  // Initialize largest as root
    l = 2 * i + 1          // left child index
    r = 2 * i + 2          // right child index

    // If left child exists and is greater than root
    @mark<l, outline, yellow> if (l < n and array[l] > array[largest]):
        @mark<l, highlight, green> largest = l
    end if

    // If right child exists and is greater than largest so far
    @mark<r, outline, yellow> if (r < n and array[r] > array[largest]):
        @mark<r, highlight, green> largest = r
    end if

    // If largest is not root
    @mark<largest, outline, yellow> if (largest != i):
        @mark<i, highlight, green> swap(array[i], array[largest])
        // Recursively heapify the affected sub-tree
        Heapify(array, n, largest)
    end if
end fun

fun Heap_Sort(@init<table> array):
    n = length(array)

    // Build a max heap
    for (i = floor(n / 2) - 1; i >= 0; i -= 1):
        Heapify(array, n, i)
    end for

    // One by one extract elements from heap
    for (i = n - 1; i > 0; i -= 1):
        // Move current root to end
        @mark<0, highlight, green> swap(array[0], array[i])

        // Call heapify on the reduced heap
        Heapify(array, i, 0)
    end for

    return array
end fun

