fun Is_Palindrome(@init<table> array):
    n = length(array)

    // Initialize two pointers: one at start, one at end
    left = 0
    right = n - 1

    // Continue comparing while left pointer is less than right pointer
    while (left < right):
        @mark<left, outline, yellow> @mark<right, outline, yellow>

        // If elements at both pointers don't match, it's not a palindrome
        if (array[left] != array[right]):
            @mark<left, highlight, green> @mark<right, highlight, green>
            return 0  // False
        end if

        // Move pointers toward center
        left += 1
        right -= 1
    end while

    return 1  // True
end fun

