fun Boyer_Moore_Majority(@init<table> nums):
    candidate = 0
    count = 0

    // Phase 1: Find candidate using Boyer-Moore voting
    for (i = 0; i < length(nums); i += 1):
        @mark<i, outline, yellow> if (count == 0):
            @mark<i, highlight, green> candidate = nums[i]
        end if

        if (nums[i] == candidate):
            @mark<i, highlight, green> count += 1
        else:
            @mark<i, outline, yellow> count -= 1
        end if
    end for

    // Phase 2: Verify the candidate is actually majority
    count = 0
    for (i = 0; i < length(nums); i += 1):
        @mark<i, outline, yellow> if (nums[i] == candidate):
            @mark<i, highlight, green> count += 1
        end if
    end for

    // Check if candidate occurs more than n/2 times
    if (count > floor(length(nums) / 2)):
        @log<info, "Majority element found"> return candidate
    else:
        @log<warn, "No majority element"> return -1
    end if
end fun

