fun Remove_Duplicates(@init<table> array):
    n = length(array)

    // Handle edge case of empty array
    if (n == 0):
        return 0
    end if

    // Index for placing unique elements
    @mark<i, outline, yellow> i = 0

    // Traverse the array starting from second element
