        @mark<j, outline, yellow> if (array[j] != array[i]):
            @mark<j, highlight, green> i += 1
            @mark<i, highlight, green> swap(array[i], array[j])
        end if
    end for

    // Return count of unique elements (i+1)
    return i + 1
end fun

