fun Remove_Duplicates(@init<table> array):
    n = length(array)

    // Handle edge case of empty array
    if (n == 0):
        return 0
    end if

    // Index for placing next unique element
    @mark<unique_idx, outline, yellow> unique_idx = 1

    // Iterate through the array starting from second element
    for (i = 1; i < n; i += 1):
        // If current element is different from previous one
        @mark<i, outline, yellow> if (array[i] != array[i - 1]):
            // Place it at the next unique position
            @mark<unique_idx, highlight, green> array[unique_idx] = array[i]
            unique_idx += 1
        end if
    end for

    // Return count of unique elements
    return unique_idx
end fun

