fun Two_Sum(@init<table> array, target):
    // Initialize two pointers at start and end of array
    left = 0
    right = length(array) - 1

    // Loop while pointers haven't crossed
    while (left < right):
        // Calculate current sum
        current_sum = array[left] + array[right]

        // If we found the target sum, return the indices
        @mark<left, outline, yellow> @mark<right, outline, yellow> if (current_sum == target):
            result = arr[left, right]
            @log<info, "Pair found"> return result
        end if

        // If current sum is less than target, move left pointer right
        if (current_sum < target):
            @mark<left, highlight, green> left += 1
        end if

        // If current sum is greater than target, move right pointer left
        if (current_sum > target):
            @mark<right, highlight, green> right -= 1
        end if
    end while

    // No valid pair found
    @log<info, "No pair found"> result = arr[-1, -1]
    return result
end fun

